mapper.insert:
/* UserMapper.insertUser : 회원가입 */
INSERT INTO USERS ( LOGIN_ID
                  , USER_KEY
                  , USER_NM
                  , USER_BRTH
                  , ZIP_CD
                  , ADDR
                  , ADDR_DTL
                  , TEL_PHONE
                  , GENDER
                  , PSWD
                  , PSWD_ERR_CNT
                  , EMAIL
                  , NICKNAME
                  , CRET_DT
                  , DEL_YN
                  , MRKT_AGRE_YN
                  , FILE_GRP_ID)
VALUES ( #{loginId}
       , #{userKey}
       , #{userNm}
       , #{userBrth}
       , #{zipCd}
       , #{addr}
       , #{addrDtl}
       , #{telPhone}
       , #{gender}
       , #{encPswd}
       , 0
       , #{email}
       , #{nickname}
       , CURRENT_TIMESTAMP
       , 'N'
       , #{mrktAgreYn}
       , #{fileGrpId})

mapper.select:
/* UserMapper.selectLoginId : 아이디 중복 체크 */
SELECT USER_KEY
FROM USERS
WHERE LOGIN_ID = #{loginId}
  AND DEL_YN = 'N'

/* UserMapper.selectEmail : 이메일 중복 체크 */
SELECT USER_KEY
FROM USERS
WHERE EMAIL = #{email}
  AND DEL_YN = 'N'

/* UserMapper.selectNickname : 닉네임 중복 체크 */
SELECT USER_KEY
FROM USERS
WHERE NICKNAME = #{nickname}
  AND DEL_YN = 'N'

/* UserMapper.selectLoginIdByNameAndEmail : 아이디 찾기 */
SELECT LOGIN_ID
FROM USERS
WHERE USER_NM = #{userNm}
  AND EMAIL = #{email}
  AND DEL_YN = 'N'

mapper.update:
/* UserMapper.updateTemporaryPassword : 임시 비밀번호 발급 업데이트 */
UPDATE USERS
SET PSWD = #{encPswd}
WHERE LOGIN_ID = #{loginId}
  AND DEL_YN = 'N'
